fn safe_sqrt(n: Float64) -> Float64
  requires: n >= 0.0;
  ensures: result >= 0.0;
{
  if n == 0.0 { return 0.0; }
  var guess = n;
  for _ in 0..50 {
    guess = (guess + n / guess) / 2.0;
  }
  return guess;
}

fn test_sqrt_positive() -> Bool { return safe_sqrt(25.0) == 5.0; }
fn test_sqrt_zero() -> Bool { return safe_sqrt(0.0) == 0.0; }
fn test_sqrt_one() -> Bool { return safe_sqrt(1.0) == 1.0; }
fn test_sqrt_large() -> Bool { return safe_sqrt(10000.0) == 100.0; }

fn main() -> Int {
  if test_sqrt_positive() && test_sqrt_zero() && test_sqrt_one() && test_sqrt_large() {
    return 1;
  }
  return 0;
}
